export function boatArt(type='cutter'){
 const scale=type==='pelagic'?1.2:type==='trawler'?1.1:1;return `<svg viewBox="0 0 400 170" xmlns="http://www.w3.org/2000/svg" role="img" aria-label="Vissersboot"><ellipse cx="200" cy="143" rx="145" ry="9" fill="#08221a" opacity=".4"/><path d="M44 100h314l-39 43H89Z" fill="#aabca4"/><path d="M80 136h246l-7 8H89Z" fill="#b78c5d"/><path d="M124 50h100v50H124Z" fill="#c6cdb6"/><path d="M116 48h115v8H116Z" fill="#62765d"/><path d="M136 61h29v22h-29Zm38 0h30v22h-30Z" fill="#4c7371"/><path d="M183 46V17m0 4h65m-15 0v68" fill="none" stroke="#a6b6a0" stroke-width="3"/><path d="M234 23l51 70m-98-76-70 77" fill="none" stroke="#899e84"/><rect x="267" y="82" width="49" height="18" rx="3" fill="#6c7e56"/><circle cx="110" cy="112" r="7" fill="#405b4b"/><path d="M31 153q30-10 60 0t60 0t60 0t60 0t60 0t60 0" fill="none" stroke="#7baca6" stroke-opacity=".4"/></svg>`;
}
